import{_ as d,C as s,o as e,c as a,a2 as o,b as i,w as l,a as n,E as c,a3 as E}from"./chunks/framework.CZGNF-7T.js";const m=JSON.parse('{"title":"프로젝트 권한 & 모듈별 공개 정책","description":"","frontmatter":{},"headers":[],"relativePath":"intro/security-policy.md","filePath":"intro/security-policy.md","lastUpdated":1786853630000}'),B={name:"intro/security-policy.md"};function g(A,t,C,u,y,D){const r=s("Mermaid");return e(),a("div",null,[t[1]||(t[1]=o('<h1 id="프로젝트-권한-모듈별-공개-정책" tabindex="-1">프로젝트 권한 &amp; 모듈별 공개 정책 <a class="header-anchor" href="#프로젝트-권한-모듈별-공개-정책" aria-label="Permalink to &quot;프로젝트 권한 &amp; 모듈별 공개 정책&quot;">​</a></h1><p>본 문서는 <strong>IBS 건설 관리 시스템</strong>의 업무/협업 도메인 (<code>work_core</code>) 및 프로젝트 데이터 관리 도메인 (분양계약/수납/회계/자금/문서, <code>ibs_global</code>)에 적용된 <strong>프로젝트 권한 및 모듈별 행 단위 데이터 보안 (Row-Level Security) 정책</strong>을 정의합니다.</p><h2 id="_1-개요-및-보안-아키텍처-원칙" tabindex="-1">1. 개요 및 보안 아키텍처 원칙 <a class="header-anchor" href="#_1-개요-및-보안-아키텍처-원칙" aria-label="Permalink to &quot;1. 개요 및 보안 아키텍처 원칙&quot;">​</a></h2><p>IBS 시스템은 **시행/건설 프로젝트 (현장)**를 중심으로 권한과 데이터가 관리됩니다. 프로젝트의 공개 여부 (<code>is_public</code>)와 유저의 프로젝트 멤버십 (<code>members</code>)에 따라 데이터 접근 수준이 아래 두 가지 기조로 명확히 분리됩니다.</p>',4)),(e(),i(E,null,{default:l(()=>[c(r,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%EC%82%AC%EC%9A%A9%EC%9E%90%20API%20%2F%20%ED%99%94%EB%A9%B4%20%EC%9A%94%EC%B2%AD%22%5D%20--%3E%20B%7B%22%EC%8A%88%ED%8D%BC%EC%9C%A0%EC%A0%80%20%2F%20%EC%97%85%EB%AC%B4%EA%B4%80%EB%A6%AC%EC%9E%90%20%3F%22%7D%0A%20%20%20%20B%20--%20Yes%20--%3E%20C%5B%22%EC%A0%84%EC%B2%B4%20%EB%8D%B0%EC%9D%B4%ED%84%B0%20%EC%A0%91%EA%B7%BC%20%EC%8A%B9%EC%9D%B8%22%5D%0A%20%20%20%20B%20--%20No%20--%3E%20D%7B%22%EB%8F%84%EB%A9%94%EC%9D%B8%20%EA%B5%AC%EB%B6%84%22%7D%0A%20%20%20%20D%20--%20%22%20%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EB%8D%B0%EC%9D%B4%ED%84%B0%20%EA%B4%80%EB%A6%AC%20(ibs_global%20%2F%20docs%20%2F%20%EC%86%8C%EC%86%A1)%20%22%20--%3E%20E%5B%22%EB%A9%A4%EB%B2%84%20%EC%A0%84%EC%9A%A9%20(Strict%20Member%20Security)%22%5D%0A%20%20%20%20E%20--%3E%20E1%7B%22%ED%95%B4%EB%8B%B9%20%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%EC%9D%98%20%EB%A9%A4%EB%B2%84%EC%9D%B8%EA%B0%80%3F%22%7D%0A%20%20%20%20E1%20--%20Yes%20--%3E%20E2%5B%22%EC%A0%91%EA%B7%BC%20%EC%8A%B9%EC%9D%B8%22%5D%0A%20%20%20%20E1%20--%20No%20--%3E%20E3%5B%22%EC%A0%9C%ED%95%9C%20(%EB%AA%A9%EB%A1%9D%EC%97%90%EC%84%9C%20%EC%A0%9C%EC%99%B8)%20403%20Forbidden%22%5D%0A%20%20%20%20D%20--%20%22%20%EC%97%85%EB%AC%B4%2F%ED%98%91%EC%97%85%20(work_core)%20%EB%AA%A8%EB%93%88%20%22%20--%3E%20F%7B%22%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EA%B3%B5%EA%B0%9C%20%EC%97%AC%EB%B6%80%3F%22%7D%0A%20%20%20%20F%20--%20%22%20%EA%B3%B5%EA%B0%9C%20%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%22%20--%3E%20G%5B%22%EC%9D%BD%EA%B8%B0%20%ED%97%88%EC%9A%A9%20(Public%20Read-Only)%22%5D%0A%20%20%20%20G%20--%3E%20G1%7B%22%EC%9A%94%EC%B2%AD%20%EC%A2%85%EB%A5%98%22%7D%0A%20%20%20%20G1%20--%20%22%20%EC%9D%BD%EA%B8%B0%20(GET%20%2F%20HEAD)%20%22%20--%3E%20G2%7B%22%EB%B9%84%EA%B3%B5%EA%B0%9C%20%2F%20%EB%B9%84%EB%B0%80%20%2F%20%EB%B8%94%EB%9D%BC%EC%9D%B8%EB%93%9C%20%EC%96%B4%EB%B6%80%3F%22%7D%0A%20%20%20%20G2%20--%20%22%20%EC%9D%BC%EB%B0%98%20%ED%95%AD%EB%AA%A9%20%22%20--%3E%20G3%5B%22%EC%97%B4%EB%9E%8C%20%EC%8A%B9%EC%9D%B8%22%5D%0A%20%20%20%20G2%20--%20%22%20%EB%B9%84%EA%B3%B5%EA%B0%9C%20%2F%20%EB%B9%84%EB%B0%80%20%2F%20%EC%88%A8%EA%B9%80%20(is_private%20%2F%20secret%20%2F%20blind)%20%22%20--%3E%20G4%5B%22%EC%A0%9C%ED%95%9C%20%2F%20403%20Forbidden%22%5D%0A%20%20%20%20G1%20--%20%22%20%EC%93%B0%EA%B8%B0%20%2F%20%EC%88%98%EC%A0%95%20%2F%20%EC%82%AD%EC%A0%9C(CUD)%20%22%20--%3E%20G5%5B%22%EB%A9%A4%EB%B2%84%20%ED%97%88%EC%9A%A9%20(%EB%B9%84%EB%A9%A4%EB%B2%84%20%EC%A0%9C%ED%95%9C%20403%20Forbidden)%22%5D%0A%20%20%20%20F%20--%20%22%20%EB%B9%84%EA%B3%B5%EA%B0%9C%20%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%22%20--%3E%20H%5B%22%EB%A9%A4%EB%B2%84%20%EC%A0%84%EC%9A%A9%20(Strict%20Member%20Security)%22%5D%0A%20%20%20%20H%20--%3E%20E1%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o('<h2 id="_2-모듈별-공개-및-접근-권한-상세-정책" tabindex="-1">2. 모듈별 공개 및 접근 권한 상세 정책 <a class="header-anchor" href="#_2-모듈별-공개-및-접근-권한-상세-정책" aria-label="Permalink to &quot;2. 모듈별 공개 및 접근 권한 상세 정책&quot;">​</a></h2><h3 id="🌐-2-1-업무-협업-work-core-영역-—-public-read-only-with-private-guard-전사-읽기-개방-비공개-보호" tabindex="-1">🌐 2.1 업무/협업 (<code>work_core</code>) 영역 — Public Read-Only with Private Guard (전사 읽기 개방 + 비공개 보호) <a class="header-anchor" href="#🌐-2-1-업무-협업-work-core-영역-—-public-read-only-with-private-guard-전사-읽기-개방-비공개-보호" aria-label="Permalink to &quot;🌐 2.1 업무/협업 (`work_core`) 영역 — Public Read-Only with Private Guard (전사 읽기 개방 + 비공개 보호)&quot;">​</a></h3><p>현장 업무의 협업 및 전사 정보 공유를 위해 <strong>공개 프로젝트의 일반 리소스에 대해서는 비멤버 직원에게도 기본 읽기 (Read-Only) 권한을 전사적으로 개방</strong>합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">모듈 / 리소스</th><th style="text-align:left;">공개 프로젝트 정책</th><th style="text-align:left;">비공개 프로젝트 정책</th><th style="text-align:left;">비공개 가드 (Private Guard)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>공지</strong> (<code>news</code>)</td><td style="text-align:left;">전직원 읽기 허용 (<code>news.read</code>) / 생성/수정/삭제는 멤버 전용</td><td style="text-align:left;">멤버 전용</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;"><strong>업무</strong> (<code>issue</code>)</td><td style="text-align:left;">전직원 읽기 허용 (<code>issue.read</code>) / 생성/수정/삭제는 멤버 전용</td><td style="text-align:left;">멤버 전용</td><td style="text-align:left;">(비공개 업무/댓글)는 비멤버 및 일반 직원에게 <strong>100% 제한</strong></td></tr><tr><td style="text-align:left;"><strong>회의록</strong> (<code>meeting</code>)</td><td style="text-align:left;">전직원 읽기 허용 (<code>meeting.read</code>) / 생성/수정/삭제는 멤버 전용</td><td style="text-align:left;">멤버 전용</td><td style="text-align:left;">비공개 회의록은 <strong>100% 제한</strong></td></tr><tr><td style="text-align:left;"><strong>게시판</strong> (<code>forum</code>)</td><td style="text-align:left;">전직원 읽기 허용 (<code>forum.read</code>) / 생성/수정/삭제는 멤버 전용</td><td style="text-align:left;">멤버 전용</td><td style="text-align:left;">(비밀글), (숨김) 항목 <strong>제한</strong></td></tr><tr><td style="text-align:left;"><strong>캘린더</strong> (<code>calendar</code>)</td><td style="text-align:left;">전직원 일정 조회 허용 (<code>calendar.read</code>)</td><td style="text-align:left;">멤버 전용</td><td style="text-align:left;">비공개 업무 및 회의 일정 <strong>제한</strong></td></tr><tr><td style="text-align:left;"><strong>활동 로그</strong> (<code>logging</code>)</td><td style="text-align:left;">전직원 활동 이력 조회 허용 (<code>activity.read</code>)</td><td style="text-align:left;">멤버 전용</td><td style="text-align:left;">비공개 업무/댓글 연관 이력 <strong>제한</strong></td></tr></tbody></table><hr><h3 id="🔐-2-2-프로젝트-데이터-관리-ibs-global-및-민감-도메인-—-strict-member-security-엄격한-멤버-전용" tabindex="-1">🔐 2.2 프로젝트 데이터 관리 (<code>ibs_global</code>) 및 민감 도메인 — Strict Member Security (엄격한 멤버 전용) <a class="header-anchor" href="#🔐-2-2-프로젝트-데이터-관리-ibs-global-및-민감-도메인-—-strict-member-security-엄격한-멤버-전용" aria-label="Permalink to &quot;🔐 2.2 프로젝트 데이터 관리 (`ibs_global`) 및 민감 도메인 — Strict Member Security (엄격한 멤버 전용)&quot;">​</a></h3><p>프로젝트가 공개 (<code>is_public=True</code>) 상태라 할지라도 <strong>기업의 재무, 계약, 회계, 수납, 분양 유니트 및 소송 데이터는 엄격히 멤버십 가입자에게만 접근을 허용</strong>하며, BOLA (IDOR) 악의적 API 파라미터 변조까지 백엔드 DB QuerySet 레벨에서 차단합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">도메인 / 메뉴</th><th style="text-align:left;">관련 모듈 / 리소스</th><th style="text-align:left;">공개 프로젝트 접근 정책</th><th style="text-align:left;">비공개 프로젝트 접근 정책</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>프로젝트 설정</code></strong></td><td style="text-align:left;">프로젝트(현장), 예산(수입/지출), 동/호수 유니트, 타입, 층별타입, 옵션 품목, 부지(Site), 소유자, 부지계약</td><td style="text-align:left;"><strong>멤버 전용</strong></td><td style="text-align:left;"><strong>멤버 전용</strong></td></tr><tr><td style="text-align:left;"><strong><code>계약 정보 관리</code></strong></td><td style="text-align:left;">차수, 분양 계약(<code>Contract</code>), 계약자, 양도양수, 해약</td><td style="text-align:left;"><strong>멤버 전용</strong></td><td style="text-align:left;"><strong>멤버 전용</strong></td></tr><tr><td style="text-align:left;"><strong><code>대금 수납 관리</code></strong></td><td style="text-align:left;">차수별 분양가, 납부회차 및 순서, 수납 내역(<code>ContractPayment</code>), 연체이율</td><td style="text-align:left;"><strong>멤버 전용</strong></td><td style="text-align:left;"><strong>멤버 전용</strong></td></tr><tr><td style="text-align:left;"><strong><code>회계 자금 관리</code></strong></td><td style="text-align:left;">프로젝트 통장, 현장 회계 계정, 현장 캐시플로우/출금 거래 내역</td><td style="text-align:left;"><strong>멤버 전용</strong></td><td style="text-align:left;"><strong>멤버 전용</strong></td></tr><tr><td style="text-align:left;"><strong><code>문서 소송 관리</code></strong></td><td style="text-align:left;">문서(<code>Document</code>), 기밀문서, 소송 사건(<code>LawsuitCase</code>), 문서 첨부파일</td><td style="text-align:left;"><strong>멤버 전용</strong></td><td style="text-align:left;"><strong>멤버 전용</strong></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">문서 (<code>docs</code>) 모듈의 이중적 분류</p><p>문서 모듈에는 소송 서류 (<code>LawsuitCase</code>), 지출 증빙, 계약서 등 법률/재무 민감 문서가 포함되어 있으므로 <code>ibs_global</code> 보안 기조 (Strict Member)를 적용하여 비멤버 접근을 원천 차단합니다.</p></div><h2 id="_3-구현-세부사항-implementation-details" tabindex="-1">3. 구현 세부사항 (Implementation Details) <a class="header-anchor" href="#_3-구현-세부사항-implementation-details" aria-label="Permalink to &quot;3. 구현 세부사항 (Implementation Details)&quot;">​</a></h2><h3 id="_3-1-백엔드-django-rest-framework-drf" tabindex="-1">3.1 백엔드 Django REST Framework (DRF) <a class="header-anchor" href="#_3-1-백엔드-django-rest-framework-drf" aria-label="Permalink to &quot;3.1 백엔드 Django REST Framework (DRF)&quot;">​</a></h3><ul><li><strong>RLS (Row-Level Security) QuerySet</strong>: <ul><li><code>ibs_global</code> &amp; <code>docs</code>: <code>queryset.filter(project__issue_project__members__user=user)</code> (또는 <code>members__user=user</code>)</li><li><code>work_core</code>: <code>queryset.filter(Q(project__is_public=True) | Q(project__members__user=user))</code> + <code>is_private=False</code> 가드 조건</li></ul></li><li><strong>Object-Level Permission (<code>work_perms.py</code>)</strong>: <ul><li><code>NewsPermission</code>, <code>ForumPermission</code>, <code>IssuePermission</code>, <code>MeetingPermission</code> 등에서 <code>request.method in permissions.SAFE_METHODS</code> 이고 <code>project.is_public == True</code> 이면 단일 객체 조회를 승인.</li></ul></li></ul><h3 id="_3-2-프론트엔드-vue-3-pinia-work-permission-ts" tabindex="-1">3.2 프론트엔드 Vue 3 / Pinia (<code>work_permission.ts</code>) <a class="header-anchor" href="#_3-2-프론트엔드-vue-3-pinia-work-permission-ts" aria-label="Permalink to &quot;3.2 프론트엔드 Vue 3 / Pinia (`work_permission.ts`)&quot;">​</a></h3><ul><li><code>usePermission</code> 스토어의 <code>can(code, projectIdentifier)</code> 메서드: <ul><li>대상 프로젝트가 <code>is_public === true</code> 이고 요청된 권한 코드가 **<code>*.read</code> (읽기 권한)**인 경우 멤버가 아니더라도 **<code>true</code>**를 반환하여 UI 상의 경고창 없이 자연스러운 Read-Only UX 제공.</li></ul></li></ul>',14))])}const _=d(B,[["render",g]]);export{m as __pageData,_ as default};
